"use client";

/**
 * @description A vertically stacked set of interactive headings that each reveal a section of content.
 */

import React from "react";
import { Accordion as AccordionRadix } from "radix-ui";
import { ChevronDownIcon } from "@radix-ui/react-icons";

import { cn } from "@/utils/class-names";

function Accordion({
  ...props
}: React.ComponentProps<typeof AccordionRadix.Root>) {
  return <AccordionRadix.Root data-slot="accordion" {...props} />;
}

function AccordionItem({
  className,
  ...props
}: React.ComponentProps<typeof AccordionRadix.Item>) {
  return (
    <AccordionRadix.Item
      data-slot="accordion-item"
      className={cn("overflow-hidden", className)}
      {...props}
    />
  );
}

function AccordionTrigger({
  className,
  children,
  ...props
}: React.ComponentProps<typeof AccordionRadix.Trigger>) {
  return (
    <AccordionRadix.Header className="flex">
      <AccordionRadix.Trigger
        data-slot="accordion-trigger"
        className={cn(
          "group flex justify-between flex-1 cursor-pointer items-center gap-1 p-1 w-full h6 border border-b-1 border-gray-6 border-x-0 border-t-0 px-2 disabled:opacity-50 disabled:cursor-not-allowed",
          className
        )}
        {...props}
      >
        {children}
        <ChevronDownIcon className="group-data-[state=open]:rotate-180 transition duration-300" />
      </AccordionRadix.Trigger>
    </AccordionRadix.Header>
  );
}

function AccordionContent({
  className,
  children,
  ...props
}: React.ComponentProps<typeof AccordionRadix.Content>) {
  return (
    <AccordionRadix.Content
      data-slot="accordion-content"
      className="bg-gray-2 data-[state=open]:animate-accordion-open data-[state=closed]:animate-accordion-closed"
      {...props}
    >
      <div className={cn("px-2 py-1", className)}>{children}</div>
    </AccordionRadix.Content>
  );
}

export { Accordion, AccordionItem, AccordionTrigger, AccordionContent };

/**
 * @description Displays a callout for user attention with contextual feedback messages.
 */
import * as React from "react";
import { cva, type VariantProps } from "class-variance-authority";
import {
  CheckCircledIcon,
  CrossCircledIcon,
  ExclamationTriangleIcon,
  InfoCircledIcon,
} from "@radix-ui/react-icons";

import { cn } from "@/utils/class-names";

const alertVariants = cva("flex gap-1 space-y-0.5 p-1 rounded-md border", {
  variants: {
    variant: {
      default: "bg-background text-foreground",
      info: "bg-info text-info-contrast border-info-contrast border border-info-contrast",
      success:
        "bg-success text-success-contrast border-success-contrast border border-success-contrast",
      warning:
        "bg-warning text-warning-contrast border-warning-contrast border border-warning-contrast",
      danger:
        "bg-danger text-danger-contrast border-danger-contrast border border-danger-contrast",
    },
  },
  defaultVariants: {
    variant: "default",
  },
});

interface AlertProps
  extends React.HTMLAttributes<HTMLDivElement>,
    VariantProps<typeof alertVariants> {}

function Alert({ className, variant, ...props }: AlertProps) {
  return (
    <div
      data-slot="alert"
      role="alert"
      className={cn(alertVariants({ variant }), className)}
      {...props}
    />
  );
}

function AlertTitle({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="alert-title"
      className={cn("font-bold", className)}
      {...props}
    />
  );
}

function AlertDescription({
  className,
  ...props
}: React.ComponentProps<"div">) {
  return <div data-slot="alert-description" {...props} />;
}

function AlertContent({ className, ...props }: React.ComponentProps<"div">) {
  return <div data-slot="alert-content" {...props} />;
}

function AlertIcon({ className, ...props }: React.ComponentProps<"div">) {
  return <div data-slot="alert-icon" {...props} />;
}

// Local AlertStatus component definition
const AlertStatus = ({
  title,
  description,
  status,
  icon,
}: {
  title: string;
  description: string;
  status: "info" | "success" | "danger" | "warning";
  icon?: React.ElementType;
}) => {
  const Icon =
    icon ||
    {
      info: InfoCircledIcon,
      success: CheckCircledIcon,
      warning: ExclamationTriangleIcon,
      danger: CrossCircledIcon,
    }[status];

  return (
    <Alert variant={status}>
      <AlertIcon>
        <Icon className="icon" />
      </AlertIcon>
      <AlertContent>
        <AlertTitle>{title}</AlertTitle>
        <AlertDescription>{description}</AlertDescription>
      </AlertContent>
    </Alert>
  );
};

export {
  Alert,
  AlertTitle,
  AlertDescription,
  AlertIcon,
  AlertContent,
  AlertStatus,
};

"use client";
