export interface RadioGroupOption {
  value: string;
  label: React.ReactNode;
  description?: React.ReactNode;
  disabled?: boolean;
}

interface FormCheckboxGroupProps extends Partial<FormRadix.FormFieldProps> {
  label?: React.ReactNode;
  labelProps?: FormRadix.FormLabelProps;
  controlProps?: FormRadix.FormControlProps;
  field?: FieldProps;
  errors?: ErrorObject<string, Record<string, any>, unknown>[];
  options: CheckboxGroupOption[];
  className?: string;
}

export const FormCheckboxGroup = React.forwardRef<
  HTMLDivElement,
  FormCheckboxGroupProps
>(
  (
    {
      label,
      labelProps,
      controlProps,
      field,
      errors,
      options,
      className,
      ...props
    },
    forwardedRef
  ) => {
    const hasError = field?.touch && errors && errors.length > 0;
    const name = props.name || field?.name || "";
    const fieldValue = Array.isArray(field?.value)
      ? (field?.value as string[])
      : [];

    const handleValueChange = React.useCallback(
      (value: string[]) => {
        if (field?.setValue) {
          // Checkbox groups use arrays, but field.setValue expects string | boolean
          // We'll cast it since checkbox groups specifically need array values
          field.setValue(value as any);
        }
      },
      [field]
    );

    return (
      <FormRadix.Field
        {...props}
        ref={forwardedRef}
        name={name}
        serverInvalid={hasError}
        className={className}
      >
        {label && (
          <div className="mb-1">
            <FormRadix.Label {...labelProps}>{label}</FormRadix.Label>
          </div>
        )}
        <FormRadix.Control {...controlProps} asChild>
          <CheckboxGroup
            value={fieldValue}
            onValueChange={handleValueChange}
            className="flex flex-col gap-1"
          >
            {options.map((option) => (
              <CheckboxGroupItem
                key={option.value}
                value={option.value}
                label={option.label}
                description={option.description}
                disabled={option.disabled}
              />
            ))}
          </CheckboxGroup>
        </FormRadix.Control>
        {hasError &&
          errors?.map((error, index) => (
            <FormRadix.Message className="text-warning-contrast" key={index}>
              {error.message}
            </FormRadix.Message>
          ))}
      </FormRadix.Field>
    );
  }
);

interface FormRadioGroupProps extends Partial<FormRadix.FormFieldProps> {
  label?: React.ReactNode;
  labelProps?: FormRadix.FormLabelProps;
  controlProps?: FormRadix.FormControlProps;
  field?: FieldProps;
  errors?: ErrorObject<string, Record<string, any>, unknown>[];
  options: RadioGroupOption[];
  className?: string;
}

export const FormRadioGroup = React.forwardRef<
  HTMLDivElement,
  FormRadioGroupProps
>(
  (
    {
      label,
      labelProps,
      controlProps,
      field,
      errors,
      options,
      className,
      ...props
    },
    forwardedRef
  ) => {
    const hasError = field?.touch && errors && errors.length > 0;
    const name = props.name || field?.name || "";
    const fieldValue = field?.value ? String(field.value) : "";

    const handleValueChange = React.useCallback(
      (value: string) => {
        if (field?.setValue) {
          field.setValue(value);
        }
      },
      [field]
    );

    return (
      <FormRadix.Field
        {...props}
        ref={forwardedRef}
        name={name}
        serverInvalid={hasError}
        className={className}
      >
        {label && (
          <div className="mb-1">
            <FormRadix.Label {...labelProps}>{label}</FormRadix.Label>
          </div>
        )}
        <FormRadix.Control {...controlProps} asChild>
          <RadioGroup
            value={fieldValue}
            onValueChange={handleValueChange}
            className="flex flex-col gap-0.5"
          >
            {options.map((option) => {
              const optionId = `${name}-${option.value}`;
              return (
                <div
                  key={option.value}
                  className={cn(
                    "flex items-start gap-1",
                    option.disabled && "opacity-50 cursor-not-allowed"
                  )}
                >
                  <RadioGroupItem
                    value={option.value}
                    id={optionId}
                    disabled={option.disabled}
                  />
                  <div className="flex flex-col gap-0.5">
                    <label
                      htmlFor={optionId}
                      className="text-sm font-medium leading-none cursor-pointer"
                    >
                      {option.label}
                    </label>
                    {option.description && (
                      <p className="text-sm text-gray-11 m-0">
                        {option.description}
                      </p>
                    )}
                  </div>
                </div>
              );
            })}
          </RadioGroup>
        </FormRadix.Control>
        {hasError &&
          errors?.map((error, index) => (
            <FormRadix.Message className="text-warning-contrast" key={index}>
              {error.message}
            </FormRadix.Message>
          ))}
      </FormRadix.Field>
    );
  }
);

interface FormAlertProps {
  formData: any;
}

export const FormAlert = ({ formData, ...props }: FormAlertProps) => {
  if (formData.fetchStatus !== "error") {
    return null;
  }

  if (!formData.error) {
    return null;
  }

  return (
    <AlertStatus status="danger" {...props} description={formData.error} />
  );
};

